<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<link rel="icon" type="image/png" href="data:image/png;base64,">
<title>AutoDoc — Sistema de gestão para despachantes</title>
<meta name="description" content="Pedidos, multas, clientes, financeiro e metas do seu escritório em um só painel. Sistema de gestão para despachantes e empresas automotivas.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<style>
:root{
  --orange:#F26522;
  --orange-hot:#FF7C3C;
  --orange-deep:#D24E10;
  --orange-soft:#FFF6F1;
  --orange-line:#FBDCC9;
  --ink:#1A2331;
  --slate:#68758A;
  --slate-light:#8D99AB;
  --line:#EDF0F4;
  --bg:#FAFBFC;
  --green:#17A55C;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
section[id]{scroll-margin-top:90px}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}
body{background:#fff;color:var(--ink);font-family:'Inter',system-ui,sans-serif;font-size:16.5px;font-weight:400;line-height:1.65;-webkit-font-smoothing:antialiased;overflow-x:hidden}
.wrap{max-width:1320px;margin:0 auto;padding:0 40px}
@media (min-width:1500px){.wrap{max-width:1420px}}
@media (max-width:640px){.wrap{padding:0 20px}}
a{color:inherit;text-decoration:none}
img{max-width:100%;display:block}
:focus-visible{outline:2px solid var(--orange);outline-offset:3px}

h1,h2,h3{font-weight:600;letter-spacing:-.028em;line-height:1.15}
h1{font-size:clamp(2.3rem,4.6vw,3.8rem);font-weight:600;line-height:1.08;letter-spacing:-.035em}
h2{font-size:clamp(1.7rem,3vw,2.5rem)}
h3{font-size:1.05rem;font-weight:600;letter-spacing:-.015em}
.eyebrow{font-size:.78rem;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--orange)}
.lede{font-size:clamp(1rem,1.25vw,1.13rem);font-weight:300;color:var(--slate);max-width:58ch;line-height:1.7}

/* header */
header{position:sticky;top:0;z-index:60;background:rgba(255,255,255,.85);backdrop-filter:blur(16px);border-bottom:1px solid var(--line);transition:box-shadow .25s,background .25s}
header.scrolled{background:rgba(255,255,255,.94);box-shadow:0 6px 24px -14px rgba(26,35,49,.22)}
.nav{display:flex;align-items:center;justify-content:space-between;height:76px;position:relative}
.brand{display:flex;align-items:center;gap:9px}
.brand img{height:30px;width:auto}
.brand span{font-size:1.18rem;font-weight:600;letter-spacing:-.03em}
.brand .o{color:var(--orange)}
.nav-links{display:flex;align-items:center;gap:34px;font-size:.92rem;font-weight:400}
.nav-links a.link{color:var(--slate);transition:color .2s}
.nav-links a.link:hover{color:var(--ink)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:12px 22px;border-radius:8px;font-size:.92rem;font-weight:500;letter-spacing:-.01em;white-space:nowrap;border:1px solid transparent;transition:background .2s,color .2s,border-color .2s,transform .15s}
.btn-primary{background:var(--orange);color:#fff}
.btn-primary:hover{background:var(--orange-hot);transform:translateY(-1px)}
.btn-outline{background:#fff;color:var(--ink);border-color:var(--line)}
.btn-outline:hover{border-color:var(--orange);color:var(--orange)}
.btn-white{background:#fff;color:var(--orange-deep)}
.btn-white:hover{transform:translateY(-1px)}
.btn-ghost-w{background:transparent;color:#fff;border-color:rgba(255,255,255,.45)}
.btn-ghost-w:hover{background:rgba(255,255,255,.12)}
.menu-btn{display:none;background:#fff;border:1px solid var(--line);border-radius:8px;padding:9px 14px;font:inherit;font-size:.85rem;font-weight:500;cursor:pointer}

/* hero */
.hero{position:relative;padding:88px 0 0;background:linear-gradient(180deg,var(--orange-soft) 0%,#fff 55%);overflow:hidden}
.hero-top{position:relative;z-index:2;max-width:820px}
.badge{display:inline-flex;align-items:center;gap:8px;background:#fff;border:1px solid var(--orange-line);color:var(--orange-deep);font-size:.78rem;font-weight:500;padding:6px 14px;border-radius:99px}
.badge i{width:6px;height:6px;border-radius:50%;background:var(--green);animation:pulse 2.4s infinite}
@keyframes pulse{50%{opacity:.35}}
.hero h1{margin:22px 0 20px}
.hero h1 em{font-style:normal;color:var(--orange)}
.hero-cta{display:flex;gap:12px;margin-top:30px;flex-wrap:wrap}
.trust{margin-top:26px;display:flex;gap:26px;flex-wrap:wrap;font-size:.87rem;font-weight:400;color:var(--slate)}
.trust b{color:var(--green);margin-right:7px;font-weight:600}

/* shot */
.hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:56px;align-items:start;position:relative;z-index:2}
.hero-top{max-width:none}
.hero-aside{display:flex;flex-direction:column;gap:18px;padding-top:6px}
/* promo card */
.promo-card{background:#fff;border:1px solid var(--orange-line);border-radius:16px;padding:30px 30px 28px;box-shadow:0 18px 44px -22px rgba(242,101,34,.34);position:relative;overflow:hidden}
.promo-card::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;background:linear-gradient(90deg,var(--orange),var(--orange-hot))}
.promo-tag{display:inline-block;font-size:.72rem;font-weight:600;letter-spacing:.09em;text-transform:uppercase;color:#fff;background:var(--orange);padding:5px 13px;border-radius:99px}
.promo-title{font-size:1.28rem;font-weight:600;letter-spacing:-.02em;line-height:1.25;margin:16px 0 10px;color:var(--ink)}
.promo-text{font-size:.93rem;font-weight:300;color:var(--slate);line-height:1.6;margin-bottom:22px}
.promo-btn{width:100%}
.promo-note{display:block;text-align:center;margin-top:14px;font-size:.8rem;font-weight:300;color:var(--slate-light)}
/* metas section balance */
#metas .split{align-items:center}
#metas .shot{align-self:center;box-shadow:0 20px 48px -18px rgba(26,35,49,.26)}

/* offer campaign (hero) */
.offer{position:relative;border-radius:20px;overflow:hidden;background:linear-gradient(150deg,#F26522 0%,#D24E10 62%,#B23F08 100%);box-shadow:0 26px 60px -24px rgba(210,78,16,.7)}
.offer-glow{position:absolute;top:-60px;right:-60px;width:280px;height:280px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.28),transparent 66%);pointer-events:none}
.offer::after{content:"";position:absolute;inset:0;background-image:repeating-linear-gradient(45deg,rgba(255,255,255,.06) 0 20px,transparent 20px 40px);pointer-events:none}
.offer-inner{position:relative;z-index:2;padding:34px 34px 30px;text-align:center;color:#fff}
.offer-tag{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.3);color:#fff;font-size:.72rem;font-weight:600;letter-spacing:.09em;text-transform:uppercase;padding:6px 14px;border-radius:99px;backdrop-filter:blur(4px)}
.offer-pulse{width:7px;height:7px;border-radius:50%;background:#fff;box-shadow:0 0 0 0 rgba(255,255,255,.7);animation:opulse 1.8s infinite}
@keyframes opulse{0%{box-shadow:0 0 0 0 rgba(255,255,255,.6)}70%{box-shadow:0 0 0 9px rgba(255,255,255,0)}100%{box-shadow:0 0 0 0 rgba(255,255,255,0)}}
.offer-lead{margin-top:18px;font-size:1rem;font-weight:400;color:rgba(255,255,255,.9)}
.offer-price{display:flex;align-items:flex-start;justify-content:center;gap:5px;margin:6px 0 4px;line-height:1}
.offer-cur{font-size:1.7rem;font-weight:600;margin-top:14px}
.offer-val{font-size:5.4rem;font-weight:800;letter-spacing:-.04em;position:relative}
.offer-cents{font-size:2.4rem;font-weight:700;vertical-align:top;position:relative;top:.35em;letter-spacing:-.02em}
.offer-per{align-self:flex-end;margin-bottom:16px;font-size:1.05rem;font-weight:400;color:rgba(255,255,255,.9)}
.offer-sub{font-size:.9rem;font-weight:300;color:rgba(255,255,255,.9);line-height:1.55;max-width:34ch;margin:8px auto 22px}
.offer-btn{width:100%;background:#fff;color:var(--orange-deep);font-weight:700;font-size:1.02rem;padding:15px;border:0;box-shadow:0 10px 26px -8px rgba(0,0,0,.4);transition:transform .16s,box-shadow .2s}
.offer-btn:hover{transform:translateY(-2px);box-shadow:0 16px 34px -8px rgba(0,0,0,.5)}
.offer-perks{list-style:none;display:flex;justify-content:center;gap:22px;margin-top:18px;flex-wrap:wrap}
.offer-perks li{display:flex;align-items:center;gap:7px;font-size:.85rem;font-weight:500;color:#fff}
.offer-perks svg{width:16px;height:16px;stroke:#fff;fill:none;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round;background:rgba(255,255,255,.2);border-radius:50%;padding:3px}

.vslide-fallback{position:absolute;left:0;right:0;bottom:0;z-index:4;text-align:center;padding:11px;background:rgba(0,0,0,.72);color:#fff;font-size:.82rem;font-weight:500;text-decoration:none}
.vslide-fallback:hover{background:rgba(0,0,0,.85)}

/* depoimentos header — enlarged, proportional */
.depo .eyebrow{font-size:1.15rem;letter-spacing:.14em}
.depo .sec-head h2{font-size:clamp(2.6rem,5vw,4.2rem);margin:18px 0 18px}
.depo .sec-head .lede{font-size:clamp(1.15rem,1.6vw,1.4rem);max-width:60ch}
.depo .sec-head{margin-bottom:60px}

/* branded cover fallback (shows if YouTube thumb fails) */
.vslide-bg{position:absolute;inset:0;z-index:0;background:
  radial-gradient(120% 80% at 50% -10%, rgba(255,255,255,.18), transparent 60%),
  linear-gradient(160deg,#F26522 0%,#D24E10 60%,#B23F08 100%)}
.vslide-bg::before{content:"";position:absolute;inset:0;background-image:repeating-linear-gradient(45deg,rgba(255,255,255,.06) 0 18px,transparent 18px 36px)}
.vslide-cover{position:absolute;inset:0;z-index:1}
.vslide-cover.is-hidden{opacity:0}
.vslide-meta{position:absolute;left:14px;bottom:14px;z-index:2;display:flex;align-items:center;gap:9px;pointer-events:none}
.vslide-quote{font-family:Georgia,serif;font-size:2.2rem;line-height:.6;color:rgba(255,255,255,.9);font-weight:700}
.vslide-tag{font-size:.78rem;font-weight:600;letter-spacing:.02em;color:#fff;background:rgba(0,0,0,.35);padding:5px 11px;border-radius:99px;backdrop-filter:blur(3px)}
.vslide.playing-hide .vslide-meta{display:none}

/* depoimentos section (bottom) */
.depo{background:var(--bg);border-block:1px solid var(--line)}
.depo-stage{max-width:340px;margin:0 auto}

/* video carousel */
.video-card{margin:0}
.vcar{position:relative;aspect-ratio:9/16;max-height:470px;border-radius:14px;overflow:hidden;background:#000;box-shadow:0 18px 40px -20px rgba(26,35,49,.4)}
.vcar-track{display:flex;height:100%;transition:transform .38s cubic-bezier(.22,.61,.36,1);touch-action:pan-y;cursor:grab}
.vcar-track.dragging{transition:none;cursor:grabbing}
.vslide{position:relative;flex:0 0 100%;height:100%}
.vslide-cover{width:100%;height:100%;object-fit:cover;display:block;pointer-events:none;user-select:none}
.vslide::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.12) 0%,transparent 30%,transparent 60%,rgba(0,0,0,.4));pointer-events:none}
.vslide-play{position:absolute;inset:0;margin:auto;width:64px;height:64px;border:0;background:transparent;cursor:pointer;display:grid;place-items:center;z-index:2}
.vslide-play .vp{width:64px;height:64px;border-radius:50%;background:var(--orange);display:grid;place-items:center;box-shadow:0 10px 26px -6px rgba(242,101,34,.75);transition:transform .18s,background .2s}
.vslide-play:hover .vp{transform:scale(1.06);background:var(--orange-hot)}
.vp svg{width:26px;height:26px;fill:#fff;stroke:none;margin-left:3px}
.vslide iframe{width:100%;height:100%;border:0;display:block}
.vcar-arrow{position:absolute;top:50%;transform:translateY(-50%);width:38px;height:38px;border-radius:50%;border:0;background:rgba(255,255,255,.92);display:grid;place-items:center;cursor:pointer;z-index:3;box-shadow:0 4px 14px rgba(0,0,0,.28);opacity:.9;transition:opacity .2s,background .2s}
.vcar-arrow:hover{opacity:1;background:#fff}
.vcar-arrow svg{width:20px;height:20px;stroke:var(--ink);fill:none;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
.vcar-arrow.prev{left:10px}
.vcar-arrow.next{right:10px}
.vcar-arrow[disabled]{opacity:0;pointer-events:none}
.vcar.playing .vcar-arrow{opacity:0;pointer-events:none}
.vcar-dots{display:flex;justify-content:center;gap:7px;margin-top:12px}
.vdot{width:7px;height:7px;border-radius:50%;background:var(--orange-line);transition:width .25s,background .25s}
.vdot.is-active{width:22px;border-radius:99px;background:var(--orange)}
.video-cap{margin-top:12px;text-align:center;font-size:.84rem;font-weight:300;color:var(--slate);line-height:1.5}

.shot-zone{position:relative;z-index:2;margin-top:60px;padding-bottom:84px}
.shot{border-radius:12px;border:1px solid var(--line);overflow:hidden;background:#fff;box-shadow:0 24px 60px -22px rgba(26,35,49,.2)}
.shot-bar{display:flex;align-items:center;gap:9px;padding:10px 15px;background:#F7F9FB;border-bottom:1px solid var(--line)}
.dots{display:flex;gap:6px}
.dots i{width:9px;height:9px;border-radius:50%;display:block;background:#DCE2E9}
.url{flex:1;max-width:320px;margin:0 auto;text-align:center;font-size:.72rem;font-weight:400;color:var(--slate-light);background:#fff;border:1px solid var(--line);border-radius:6px;padding:4px 10px}
.shot img{width:100%}
.shot-note{margin-top:16px;text-align:center;font-size:.76rem;font-weight:300;color:var(--slate-light)}

/* strip */
.strip{background:var(--bg);border-block:1px solid var(--line)}
.strip-grid{display:grid;grid-template-columns:repeat(4,1fr)}
.strip-cell{padding:38px 28px;border-left:1px solid var(--line)}
.strip-cell:first-child{border-left:none}
.strip-cell{display:flex;align-items:center;gap:16px}
.strip-ico{flex:none;width:44px;height:44px;border-radius:11px;background:var(--orange-soft);border:1px solid var(--orange-line);display:grid;place-items:center}
.strip-ico svg{width:22px;height:22px;stroke:var(--orange);fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.strip-cell b{display:block;font-size:1.9rem;font-weight:600;letter-spacing:-.04em;line-height:1;color:var(--orange)}
.strip-cell span{display:block;margin-top:9px;font-size:.87rem;font-weight:300;color:var(--slate)}

section{padding:104px 0}
.sec-head{max-width:58ch;margin-bottom:56px}
.sec-head h2{margin:12px 0 14px}
.center{margin-inline:auto;text-align:center}
.center .lede{margin-inline:auto}

.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:30px;transition:border-color .22s,box-shadow .22s,transform .22s}
.card:hover{border-color:var(--orange-line);box-shadow:0 12px 34px -14px rgba(242,101,34,.28);transform:translateY(-3px)}
.ico{width:42px;height:42px;border-radius:10px;background:var(--orange-soft);display:grid;place-items:center;margin-bottom:18px}
.ico svg{width:20px;height:20px;stroke:var(--orange);fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.card h3{margin-bottom:8px}
.card p{color:var(--slate);font-size:.92rem;font-weight:300;line-height:1.65}

/* fluxo */
.flow{background:var(--bg);border-block:1px solid var(--line)}
.flow-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:48px}
.step{background:#fff;border:1px solid var(--line);border-radius:12px;padding:28px;transition:border-color .22s}
.step:hover{border-color:var(--orange-line)}
.step .n{width:28px;height:28px;border-radius:7px;background:var(--orange-soft);color:var(--orange);display:grid;place-items:center;font-size:.82rem;font-weight:600;margin-bottom:16px}
.step h3{margin-bottom:7px}
.step p{color:var(--slate);font-size:.88rem;font-weight:300;line-height:1.6}

/* split */
.split{display:grid;grid-template-columns:1fr 1fr;gap:68px;align-items:center}
.checks{list-style:none;margin-top:26px;display:grid;gap:12px}
.checks li{display:flex;gap:12px;align-items:flex-start;font-size:.95rem;font-weight:400;color:var(--ink)}
.checks svg{width:18px;height:18px;flex:none;margin-top:3px;stroke:var(--green);fill:none;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}

/* cta */
.cta{background:var(--orange);color:#fff}
.cta-inner{display:grid;grid-template-columns:1.35fr .65fr;gap:48px;align-items:center}
.cta .eyebrow{color:rgba(255,255,255,.82)}
.cta h2{margin:12px 0 14px;font-weight:600}
.cta p{color:rgba(255,255,255,.9);max-width:52ch;font-weight:300}
.cta-actions{display:flex;flex-direction:column;gap:11px}
.cta-contact{display:grid;grid-template-columns:1fr 1fr;gap:11px}

/* footer */
footer{background:#fff;border-top:1px solid var(--line);color:var(--slate);padding:64px 0 34px;font-size:.9rem}
.foot{display:flex;justify-content:space-between;gap:40px;flex-wrap:wrap}
.foot .brand{margin-bottom:14px}
.foot p{font-weight:300;max-width:36ch}
.foot-cols{display:flex;gap:64px;flex-wrap:wrap}
.foot-col{display:flex;flex-direction:column;gap:11px}
.foot-h{font-size:.74rem;font-weight:600;letter-spacing:.09em;text-transform:uppercase;color:var(--slate-light);margin-bottom:2px}
.foot-col a{color:var(--ink);font-weight:400;font-size:.92rem}
.foot-col a:hover{color:var(--orange)}
.foot-bottom{margin-top:44px;padding-top:22px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;font-size:.8rem;font-weight:300;color:var(--slate-light)}


/* precos */
.pricing{background:var(--orange-soft);border-block:1px solid var(--orange-line)}
.plan{max-width:560px;margin:0 auto;background:#fff;border:1px solid var(--orange-line);border-radius:16px;overflow:hidden;box-shadow:0 20px 50px -24px rgba(242,101,34,.3)}
.plan-top{padding:40px 44px 34px;text-align:center;position:relative}
.plan-top::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;background:var(--orange)}
.plan-badge{display:inline-block;font-size:.72rem;font-weight:600;letter-spacing:.09em;text-transform:uppercase;color:var(--orange);background:var(--orange-soft);border:1px solid var(--orange-line);padding:5px 13px;border-radius:99px}
.plan-price{display:flex;align-items:flex-start;justify-content:center;gap:5px;margin:20px 0 4px}
.plan-price .cur{font-size:1.5rem;font-weight:500;color:var(--slate);margin-top:11px}
.plan-price .val{font-size:4.2rem;font-weight:600;letter-spacing:-.045em;line-height:.95;color:var(--ink)}
.plan-price .per{align-self:flex-end;margin-bottom:12px;font-size:1rem;font-weight:300;color:var(--slate)}
.plan-sub{font-size:.92rem;font-weight:300;color:var(--slate)}
.plan-list{list-style:none;padding:30px 44px;border-top:1px solid var(--line);display:grid;gap:14px}
.plan-list li{display:flex;gap:12px;align-items:center;font-size:.94rem;font-weight:400;color:var(--ink)}
.plan-list svg{width:18px;height:18px;flex:none;stroke:var(--green);fill:none;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.plan-add{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:22px 44px;background:var(--bg);border-top:1px solid var(--line)}
.plan-add .add-l{font-size:.9rem;font-weight:400;color:var(--ink)}
.plan-add .add-l small{display:block;font-size:.8rem;font-weight:300;color:var(--slate);margin-top:2px}
.plan-add .add-r{white-space:nowrap;font-size:1.5rem;font-weight:600;letter-spacing:-.03em;color:var(--orange)}
.plan-add .add-r span{font-size:.82rem;font-weight:300;color:var(--slate);margin-left:3px}
.plan-cta{padding:0 44px 40px}
.plan-cta .btn{width:100%}
.plan-foot{text-align:center;margin-top:24px;font-size:.84rem;font-weight:300;color:var(--slate-light)}
@media (max-width:560px){
  .plan-top,.plan-list,.plan-add,.plan-cta{padding-left:26px;padding-right:26px}
  .plan-add{flex-direction:column;align-items:flex-start;gap:8px}
}

.reveal{opacity:0;transform:translateY(16px);transition:opacity .6s ease,transform .6s ease}
.reveal.in{opacity:1;transform:none}

@media (max-width:980px){
  .nav-links{display:none}
  .nav-links.open{display:flex;position:absolute;top:76px;left:-28px;right:-28px;flex-direction:column;align-items:stretch;gap:16px;background:#fff;border-bottom:1px solid var(--line);padding:24px 28px}
  .menu-btn{display:block}
  .cards,.flow-grid,.strip-grid{grid-template-columns:1fr 1fr}
  .strip-cell:nth-child(3){border-left:none}
  .strip-cell:nth-child(n+3){border-top:1px solid var(--line)}
  .hero-grid{grid-template-columns:1fr;gap:40px}
  .hero-aside{max-width:520px}
