<script>
const io = new IntersectionObserver(es=>{
  es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}});
},{threshold:.1});
document.querySelectorAll('.reveal').forEach((el,i)=>{
  el.style.transitionDelay=(i%3)*70+'ms';
  io.observe(el);
});
const mb=document.getElementById('menuBtn'), nl=document.getElementById('navLinks');
mb.addEventListener('click',()=>{
  const open=nl.classList.toggle('open');
  mb.setAttribute('aria-expanded',open);
});
nl.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{
  nl.classList.remove('open');mb.setAttribute('aria-expanded','false');
}));
const hdr=document.querySelector('header');
const onScroll=()=>hdr.classList.toggle('scrolled',window.scrollY>8);
onScroll();window.addEventListener('scroll',onScroll,{passive:true});

// Video testimonials carousel (swipe/drag)
(function(){
  const car=document.getElementById('vcar');
  if(!car) return;
  const track=document.getElementById('vcarTrack');
  const slides=Array.from(track.children);
  const dots=Array.from(document.getElementById('vcarDots').children);
  const prev=document.getElementById('vcarPrev');
  const next=document.getElementById('vcarNext');
  let idx=0, startX=0, curX=0, dragging=false, moved=false, w=0;

  function setDots(){dots.forEach((d,i)=>d.classList.toggle('is-active',i===idx));}
  function updateArrows(){prev.disabled=idx===0;next.disabled=idx===slides.length-1;}
  function go(i){
    idx=Math.max(0,Math.min(slides.length-1,i));
    track.style.transform='translateX('+(-idx*100)+'%)';
    setDots();updateArrows();
  }
  function play(slide){
    const id=slide.dataset.id;
    if(slide.querySelector('iframe')) return;
    const ifr=document.createElement('iframe');
    ifr.src='https://www.youtube-nocookie.com/embed/'+id+'?autoplay=1&rel=0&modestbranding=1&playsinline=1';
    ifr.title='Depoimento em vídeo';
    ifr.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';
    ifr.setAttribute('allowfullscreen','');
    ifr.loading='eager';
    slide.innerHTML='';
    slide.appendChild(ifr);
    // Safety net: if the embed is blocked by the video's settings, offer a direct link.
    const fallback=document.createElement('a');
    fallback.className='vslide-fallback';
    fallback.href='https://www.youtube.com/shorts/'+id;
    fallback.target='_blank';
    fallback.rel='noopener';
    fallback.textContent='Assistir no YouTube ↗';
    slide.appendChild(fallback);
    car.classList.add('playing');
  }

  // play on button OR anywhere on the cover (more forgiving on touch)
  slides.forEach(s=>{
    s.addEventListener('click',e=>{
      if(e.target.closest('iframe')||e.target.closest('.vslide-fallback'))return;
      if(!moved) play(s);
    });
  });
  prev.addEventListener('click',()=>go(idx-1));
  next.addEventListener('click',()=>go(idx+1));

  // pointer drag / swipe
  function down(x){dragging=true;moved=false;startX=x;curX=x;w=car.clientWidth;track.classList.add('dragging');}
  function move(x){
    if(!dragging)return;
    curX=x;const dx=x-startX;
    if(Math.abs(dx)>6)moved=true;
    track.style.transform='translateX('+(-idx*100 + (dx/w)*100)+'%)';
  }
  function up(){
    if(!dragging)return;
    dragging=false;track.classList.remove('dragging');
    const dx=curX-startX;const th=w*0.18;
    if(dx>th)go(idx-1);
    else if(dx<-th)go(idx+1);
    else go(idx);
  }
  track.addEventListener('pointerdown',e=>{if(car.classList.contains('playing'))return;down(e.clientX);});
  window.addEventListener('pointermove',e=>move(e.clientX));
  window.addEventListener('pointerup',up);
  // touch fallback
  track.addEventListener('touchstart',e=>{if(car.classList.contains('playing'))return;down(e.touches[0].clientX);},{passive:true});
  track.addEventListener('touchmove',e=>move(e.touches[0].clientX),{passive:true});
  track.addEventListener('touchend',up);

  updateArrows();
})();
</script>
